/// The emitted shape rendered as the Rust literal a reader pastes into the table.
///
/// A diagnostic that hands over the answer, because the alternative is a reader deriving
/// fifty-eight digests by hand from a message that only says they were wrong.
fn literal(emitted: &[(&str, u64)]) -> String {
    let rows: Vec<String> = emitted
        .iter()
        .map(|(name, digest)| format!("    (\"{name}\", {digest:#018x}),"))
        .collect();
    format!(
        "const NEXT_BUNDLE_SHAPE: [(&str, u64); {}] = [\n{}\n];",
        emitted.len(),
        rows.join("\n")
    )
}

#[test]
fn the_schema_bundle_describes_every_contract_root_and_every_plugin_config() {
    let bundle = schema_bundle();
    assert_eq!(bundle["version"], SCHEMA_BUNDLE_VERSION);

    let roots = bundle["roots"].as_object().expect("roots is an object");

    let sorted = |names: &[&str]| {
        let mut owned: Vec<String> = names.iter().map(|name| (*name).to_owned()).collect();
        owned.sort_unstable();
        owned
    };

    // The version counts the rows, so appending one without bumping it — or bumping it
    // without appending one — fails here rather than shipping a version that describes
    // no shape.
    assert_eq!(
        SCHEMA_BUNDLE_VERSION as usize,
        PUBLISHED_BUNDLES.len(),
        "SCHEMA_BUNDLE_VERSION is {SCHEMA_BUNDLE_VERSION} but PUBLISHED_BUNDLES has {} row(s). \
         Append a row for the new shape and bump the version to match.",
        PUBLISHED_BUNDLES.len()
    );

    for (index, (version, published)) in PUBLISHED_BUNDLES.iter().enumerate() {
        assert_eq!(
            *version as usize,
            index + 1,
            "PUBLISHED_BUNDLES row {index} claims version {version}; rows are the versions \
             in order, so row {index} is version {}.",
            index + 1
        );
        // Once a version records the shape, no later version may record less: a row that
        // fell back to names would silently stop noticing a changed root.
        assert!(
            *version < SHAPES_FROM
                || matches!(published, Published::Shapes(_) | Published::Whole { .. }),
            "version {version} is at or past {SHAPES_FROM} and must record every root's \
             schema, not its name alone."
        );
        // And once a version records the whole document, no later version records less.
        assert!(
            *version < WHOLE_FROM || matches!(published, Published::Whole { .. }),
            "version {version} is at or past {WHOLE_FROM} and must record every plugin's \
             configuration and every root the binary adds beside the engine's roots."
        );
        // A shape may not be republished under a second version, and a version may not
        // describe two shapes — either would make the version useless for the SDK that
        // reads it.
        assert!(
            !PUBLISHED_BUNDLES[..index].iter().any(|(_, earlier)| {
                match (earlier, published) {
                    (Published::Names(earlier), Published::Names(now)) => {
                        sorted(earlier) == sorted(now)
                    }
                    (Published::Shapes(earlier), Published::Shapes(now)) => {
                        let mut earlier = earlier.to_vec();
                        let mut now = now.to_vec();
                        earlier.sort_unstable();
                        now.sort_unstable();
                        earlier == now
                    }
                    (
                        Published::Whole {
                            roots: earlier_roots,
                            beside: earlier_beside,
                        },
                        Published::Whole { roots, beside },
                    ) => {
                        let sorted = |entries: &[(&'static str, u64)]| {
                            let mut entries = entries.to_vec();
                            entries.sort_unstable();
                            entries
                        };
                        sorted(earlier_roots) == sorted(roots)
                            && sorted(earlier_beside) == sorted(beside)
                    }
                    _ => false,
                }
            }),
            "version {version} republishes an earlier version's exact shape; if the \
             shape did not change, the version must not either."
        );
    }

    let (_, expected) = PUBLISHED_BUNDLES
        .iter()
        .find(|(version, _)| *version == SCHEMA_BUNDLE_VERSION)
        .expect("PUBLISHED_BUNDLES lists the current SCHEMA_BUNDLE_VERSION");

    assert_eq!(
        sorted(&roots.keys().map(String::as_str).collect::<Vec<_>>()),
        sorted(&expected.names()),
        "the bundle's roots are not what version {SCHEMA_BUNDLE_VERSION} publishes. Append a \
         row to PUBLISHED_BUNDLES with the new shape and bump SCHEMA_BUNDLE_VERSION to match \
         — an SDK generated against the old version would otherwise silently emit the wrong \
         models."
    );

    for root in expected.names() {
        assert!(roots[root].is_object(), "the bundle is missing {root}");
    }

    // And what each root *contains*, which the root names alone cannot see. A property
    // added to `CopyReport` is a new field in both SDKs' generated models exactly as a new
    // root is a new model, so it moves the version or it fails here.
    if let Published::Shapes(published)
    | Published::Whole {
        roots: published, ..
    } = expected
    {
        let mut emitted: Vec<(&str, u64)> = roots
            .iter()
            .map(|(name, schema)| (name.as_str(), digest(schema)))
            .collect();
        emitted.sort_unstable();
        let mut recorded = published.to_vec();
        recorded.sort_unstable();
        assert_eq!(
            emitted,
            recorded,
            "the schemas version {SCHEMA_BUNDLE_VERSION} publishes are not the ones the \
             binary emits. If this change is deliberate, append a row to PUBLISHED_BUNDLES \
             and bump SCHEMA_BUNDLE_VERSION to match; the row to paste is:\n{}",
            literal(&emitted)
        );
    }
    // And what a whole row records beside them: every plugin's configuration schema, which moves
    // both SDKs' models exactly as an engine root does. Its `binary/<root>` entries are the
    // binary's to verify; nothing else may be recorded there.
    if let Published::Whole {
        beside: published, ..
    } = expected
    {
        assert!(
            published
                .iter()
                .all(|(name, _)| name.starts_with("plugin_config/") || name.starts_with("binary/")),
            "a whole row records plugin_config/<kind> and binary/<root> entries alone: \
             {published:?}"
        );
        let emitted = plugin_configs(&bundle);
        let mut recorded: Vec<(String, u64)> = published
            .iter()
            .filter(|(name, _)| name.starts_with("plugin_config/"))
            .map(|(name, digest)| ((*name).to_owned(), *digest))
            .collect();
        recorded.sort_unstable();
        let rows: Vec<String> = emitted
            .iter()
            .map(|(name, digest)| format!("    (\"{name}\", {digest:#018x}),"))
            .collect();
        assert_eq!(
            emitted,
            recorded,
            "the plugin configurations version {SCHEMA_BUNDLE_VERSION} publishes are not the \
             ones the bundle emits. If this change is deliberate, append a row to \
             PUBLISHED_BUNDLES and bump SCHEMA_BUNDLE_VERSION to match; its plugin_config \
             entries are:\n{}",
            rows.join("\n")
        );
    }

    let plugins = bundle["plugin_config"]
        .as_object()
        .expect("plugin_config is an object");
    let mut kinds: Vec<&String> = plugins.keys().collect();
    kinds.sort();
    assert_eq!(
        kinds,
        [
            "github-projects",
            "in-memory",
            "linear",
            "local-md",
            "subprocess"
        ]
    );
}

#[test]
fn a_response_carries_the_plan_that_produced_it_and_round_trips() {
    // `--explain` renders this; `--json` carries it. The point is that two sources
    // of differing capability answer one query correctly by different routes, and
    // a user can see which.
    let response = QueryResponse {
        items: vec![Task { version: None,
            id: NativeId::from("ENG-1"),
            key: None,
            title: "Land the contract".to_owned(),
            content: None,
            status: Status {
                category: StatusCategory::InProgress,
                name: "In Review".to_owned(),
            },
            priority: Priority::None,
            labels: Vec::new(),
            project: None,
            url: None,
            location: None,
            created_at: None,
            updated_at: None,
            metadata: Default::default(),
            repositories: Vec::new(),
            delivers: Vec::new(),
            delivered_by: Vec::new(),
            classification: Default::default(),
            assignees: None,
        }],
        // The hex of
        // `{"query":"0123456789abcdef","streams":[{"source":"work","stream":"items","cursor":"50"}]}`
        // — the fingerprint of the query that minted it, and one stream resuming at the
        // source's own opaque cursor. Spelled out rather than built, so a change to the
        // document a token carries has to be made here too and cannot pass unnoticed.
        next: Some(
            PageToken::parse("7b227175657279223a2230313233343536373839616263646566222c2273747265616d73223a5b7b22736f75726365223a22776f726b222c2273747265616d223a226974656d73222c22637572736f72223a223530227d5d7d")
                .expect("a token this engine issued"),
        ),
        plan: QueryPlan {
            per_source: vec![
                SourcePlan {
                    source: source("work"),
                    kind: "in-memory".to_owned(),
                    pushed_down: vec![Predicate::Label, Predicate::Status],
                    applied_locally: Vec::new(),
                    emulated: Vec::new(),
                    unavailable: Vec::new(),
                    pages_fetched: 1,
                },
                SourcePlan {
                    source: source("notes"),
                    kind: "local-md".to_owned(),
                    pushed_down: Vec::new(),
                    applied_locally: vec![Predicate::Label, Predicate::SearchContent],
                    emulated: vec![Predicate::ReverseDependencies],
                    unavailable: vec![Predicate::Project],
                    pages_fetched: 4,
                },
            ],
        },
        errors: vec![SourceFailure {
            source: source("gh-main"),
            error: SourceError::Unavailable {
                message: "no route to host".to_owned(),
            },
        }],
        unanswered: vec![onetaskgraph_core::Unanswered::Source(SourceFailure {
            source: source("vault"),
            error: SourceError::Auth {
                message: "set environment variable VAULT_KEY".to_owned(),
            },
        })],
    };

    let encoded = serde_json::to_string(&response).expect("encodes");
    let decoded: QueryResponse<Task> = serde_json::from_str(&encoded).expect("decodes");
    assert_eq!(decoded, response);

    // One source failing never fails the whole query: the other results stand.
    assert_eq!(decoded.items.len(), 1);
    assert_eq!(decoded.errors.len(), 1);
    assert_eq!(decoded.plan.per_source.len(), 2);
    assert_eq!(QueryPlan::default().per_source, Vec::new());
}

#[test]
fn every_predicate_serialises_as_kebab_case_so_explain_output_is_stable() {
    for (predicate, wire) in [
        (Predicate::Label, "label"),
        (Predicate::Status, "status"),
        (Predicate::SearchTitle, "search-title"),
        (Predicate::SearchContent, "search-content"),
        (Predicate::Project, "project"),
        (Predicate::ReverseDependencies, "reverse-dependencies"),
    ] {
        assert_eq!(
            serde_json::to_value(predicate).expect("encodes"),
            serde_json::json!(wire)
        );
        assert_eq!(
            serde_json::from_value::<Predicate>(serde_json::json!(wire)).expect("decodes"),
            predicate
        );
    }
}

#[test]
fn a_failure_is_refused_unless_waiting_could_change_the_answer() {
    let message = || "said so".to_owned();
    for (error, class) in [
        (
            SourceError::RateLimited {
                retry_after_seconds: Some(30),
                message: None,
            },
            FailureClass::Transient,
        ),
        (
            SourceError::Unavailable { message: message() },
            FailureClass::Transient,
        ),
        (
            SourceError::Refused { message: message() },
            FailureClass::Refused,
        ),
        (
            SourceError::Config { message: message() },
            FailureClass::Refused,
        ),
        (
            SourceError::Auth { message: message() },
            FailureClass::Refused,
        ),
        (
            SourceError::Malformed { message: message() },
            FailureClass::Refused,
        ),
    ] {
        assert_eq!(classify(Some(&error)), class, "{error:?}");

        // A partial answer's entry carries the class the one mapping gives, beside the
        // error itself — and a document read back in has it recomputed, not trusted.
        let failure = SourceFailure {
            source: source("work"),
            error: error.clone(),
        };
        let written = serde_json::to_value(&failure).expect("an entry renders");
        assert_eq!(written["class"], json!(class), "{written}");
        let mut forged = written.clone();
        forged["class"] = json!(if class == FailureClass::Refused {
            "transient"
        } else {
            "refused"
        });
        let read: SourceFailure = serde_json::from_value(forged).expect("an entry reads");
        assert_eq!(
            serde_json::to_value(&read).expect("renders"),
            written,
            "a class read in is recomputed from the error it classifies"
        );
    }
    // No source caused it: the engine decided, and it will decide the same way again.
    assert_eq!(classify(None), FailureClass::Refused);
}

#[test]
fn a_failure_document_names_what_failed_where_and_takes_a_wrapped_failures_class() {
    let document = |failure: Failure| {
        serde_json::to_value(FailureDocument {
            failure,
            expected: onetaskgraph_core::ExpectedWrite::default(),
            held: None,
            predates_write: false,
            oversize: Vec::new(),
        })
        .expect("a failure document renders")
    };

    // Nothing a source said: refused, with the engine's own name for it and no source.
    let missing = EngineError::NoSuchItem {
        id: "work:NOPE".to_owned(),
    };
    assert_eq!(
        document(Failure::from(&missing)),
        json!({"failure": {"class": "refused", "kind": "no-such-item", "source": null,
                           "message": missing.to_string(), "retry_after_seconds": null}})
    );

    // A failure about one configured source names it, although no source error caused it.
    let unwritable = EngineError::NotWritable {
        name: "board".to_owned(),
        kind: "in-memory".to_owned(),
    };
    assert_eq!(
        document(Failure::from(&unwritable))["failure"],
        json!({"class": "refused", "kind": "not-writable", "source": "board",
               "message": unwritable.to_string(), "retry_after_seconds": null})
    );

    // A wrapper takes the class and kind of what it wraps, however deep — here a copy that
    // could not be undone, around a source refusing it for a rate limit that named a wait.
    // The message is still the whole failure's, which is what the stderr line carries.
    let limited = EngineError::CopyNotUndone {
        error: Box::new(EngineError::SourceRefused {
            name: "board".to_owned(),
            error: SourceError::RateLimited {
                retry_after_seconds: Some(90),
                message: Some("the primary limit".to_owned()),
            },
        }),
        left_behind: LeftBehind::new("board:ITEM-1".parse().expect("a qualified id")),
        refusal: SourceError::Refused {
            message: "not yours to delete".to_owned(),
        },
    };
    assert_eq!(
        document(Failure::from(&limited))["failure"],
        json!({"class": "transient", "kind": "rate-limited", "source": "board",
               "message": limited.to_string(), "retry_after_seconds": 90})
    );

    // A copy whose create was answered malformed takes the class and kind of that answer,
    // and names the destination; its message is the whole failure's, warning of residue.
    let uncertain = EngineError::CopyDestinationUncertain {
        error: Box::new(EngineError::SourceRefused {
            name: "board".to_owned(),
            error: SourceError::Malformed {
                message: "the plugin's answer to write_task is not the shape it promises"
                    .to_owned(),
            },
        }),
        destination: "board".to_owned(),
        operation: "write_task".to_owned(),
    };
    assert_eq!(
        document(Failure::from(&uncertain))["failure"],
        json!({"class": "refused", "kind": "malformed", "source": "board",
               "message": uncertain.to_string(), "retry_after_seconds": null})
    );
    assert!(
        uncertain
            .to_string()
            .contains("board may hold an item it could not take back"),
        "{uncertain}"
    );

    let unbuilt = EngineError::DestinationUnavailable {
        name: "notes".to_owned(),
        error: SourceError::Unavailable {
            message: "connection refused".to_owned(),
        },
    };
    let unbuilt_failure = document(Failure::from(&unbuilt));
    assert_eq!(unbuilt_failure["failure"]["class"], "transient");
    assert_eq!(unbuilt_failure["failure"]["kind"], "unavailable");
    assert_eq!(unbuilt_failure["failure"]["source"], "notes");

    // A comment verb is one call to one source, and what that source said is what it failed of.
    let limited_comment = EngineError::SourceFailed {
        name: "board".to_owned(),
        error: SourceError::RateLimited {
            retry_after_seconds: Some(30),
            message: None,
        },
    };
    assert_eq!(
        document(Failure::from(&limited_comment))["failure"],
        json!({"class": "transient", "kind": "rate-limited", "source": "board",
               "message": limited_comment.to_string(), "retry_after_seconds": 30})
    );
    let uncommentable = document(Failure::from(&EngineError::NoComments {
        name: "notes".to_owned(),
        kind: "local-md".to_owned(),
    }));
    assert_eq!(uncommentable["failure"]["source"], "notes");

    // Every engine failure no source caused, by the name a caller sees.
    for (error, kind) in [
        (
            EngineError::UnknownSource {
                name: "elsewhere".to_owned(),
                configured: "work".to_owned(),
            },
            "unknown-source",
        ),
        (
            EngineError::Token {
                message: "not this query's".to_owned(),
            },
            "page-token",
        ),
        (EngineError::NoSources, "no-sources"),
        (
            EngineError::NoDocuments {
                name: "notes".to_owned(),
                kind: "local-md".to_owned(),
            },
            "no-documents",
        ),
        (
            EngineError::NoComments {
                name: "notes".to_owned(),
                kind: "local-md".to_owned(),
            },
            "no-comments",
        ),
        (
            EngineError::CommentsNotWritable {
                name: "notes".to_owned(),
                kind: "in-memory".to_owned(),
            },
            "not-writable",
        ),
        (
            EngineError::NoSuchTask {
                id: "notes:T-9".to_owned(),
            },
            "no-such-item",
        ),
        (
            EngineError::NoSuchComment {
                task: "notes:T-1".to_owned(),
                comment: "C-9".to_owned(),
            },
            "no-such-comment",
        ),
        (
            EngineError::StaleOrigin {
                item: "plans:A".to_owned(),
                origin: "board:ITEM-1".to_owned(),
            },
            "stale-origin",
        ),
        (
            EngineError::NotAMember {
                id: "plans:T-9".parse().expect("a qualified id"),
                projects: vec!["plans:P-1".parse().expect("a qualified id")],
            },
            "not-a-member",
        ),
        (
            EngineError::UnrecordedMember {
                item: "plans:T-2".parse().expect("a qualified id"),
                member: "plans:T-1".parse().expect("a qualified id"),
                destination: source("board"),
            },
            "unrecorded-member",
        ),
    ] {
        let rendered = document(Failure::from(&error));
        assert_eq!(rendered["failure"]["class"], "refused", "{error:?}");
        assert_eq!(rendered["failure"]["kind"], kind, "{error:?}");
    }

    // A configuration this product will not run on, and a failure the command decided.
    for (error, kind) in [
        (
            ConfigError::Syntax {
                path: "onetaskgraph.yaml".into(),
                message: "bad".to_owned(),
            },
            "config-syntax",
        ),
        (
            ConfigError::Read {
                path: "onetaskgraph.yaml".into(),
                message: "denied".to_owned(),
            },
            "config-read",
        ),
        (
            ConfigError::Setting {
                key: "page_size".to_owned(),
                message: "not a number".to_owned(),
                next: "use one".to_owned(),
            },
            "config-setting",
        ),
    ] {
        assert_eq!(
            document(Failure::from(&error))["failure"],
            json!({"class": "refused", "kind": kind, "source": null,
                   "message": error.to_string(), "retry_after_seconds": null})
        );
    }
    let decided = Failure::decided("invalid-id", "not qualified");
    assert_eq!(decided.message(), "not qualified");
    assert_eq!(document(decided)["failure"]["kind"], "invalid-id");
}

